import { expect, test } from "../../fixtures";
import { API_URL } from "../../playwright.config";

test("requests without a session are rejected", { tag: "@AUTH-05" }, async ({ playwright }) => {
  // Arrange: a fresh context with no Authorization header and no session cookie
  const anon = await playwright.request.newContext({ baseURL: API_URL });

  try {
    // Act
    const response = await anon.get("/api/me");

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(401);
    const json = JSON.parse(body);
    expect(json.error?.code, body).toBe("not_authenticated");
  } finally {
    await anon.dispose();
  }
});
